import { useState, useEffect } from 'react';

export function useTranslate(language) {
  const [translations, setTranslations] = useState({});
  const [loading, setLoading] = useState(false);

  // Funzione per caricare dinamicamente le traduzioni
  const loadTranslations = async (lang) => {
    if (translations[lang]) return; // Già caricate

    setLoading(true);
    try {
      // Import dinamico del file di traduzione
      const translationModule = await import(`../i18n/${lang}/common.json`);

      setTranslations((prev) => ({
        ...prev,
        [lang]: translationModule.default || translationModule,
      }));
    } catch (error) {
      console.error(`Error loading translations for ${lang}:`, error);

      // Fallback su inglese se la lingua non esiste
      if (lang !== 'en') {
        try {
          const fallbackModule = await import(`../i18n/en/common.json`);
          setTranslations((prev) => ({
            ...prev,
            [lang]: fallbackModule.default || fallbackModule,
          }));
        } catch (fallbackError) {
          console.error('Error loading fallback translations:', fallbackError);
        }
      }
    } finally {
      setLoading(false);
    }
  };

  // Carica le traduzioni quando cambia la lingua
  useEffect(() => {
    loadTranslations(language);
  }, [language]);

  const translate = (key, params = {}) => {
    const currentTranslations = translations[language] || translations['en'] || {};

    // Naviga attraverso le chiavi annidate (es. "general.customize")
    const keys = key.split('.');
    let value = currentTranslations;

    for (const k of keys) {
      value = value?.[k];
      if (value === undefined) break;
    }

    if (typeof value === 'string') {
      // Sostituisce i parametri nel formato { param }
      return value.replace(/\{\s*(\w+)\s*\}/g, (match, paramKey) => {
        return params[paramKey] || match;
      });
    }

    return key; // Fallback se la traduzione non è trovata
  };

  return { translate, loading };
}
